import{_ as t,o as a,c as i,a3 as s}from"./chunks/framework.WFmvnizL.js";const g=JSON.parse('{"title":"Agent development","description":"Develop Nezha Agent with local builds, isolated test identities, metrics and protobuf data flow, immutable runtime configuration, task gates, and cross-repository compatibility testing.","frontmatter":{"description":"Develop Nezha Agent with local builds, isolated test identities, metrics and protobuf data flow, immutable runtime configuration, task gates, and cross-repository compatibility testing.","outline":"deep"},"headers":[],"relativePath":"en_US/developer/agent-development.md","filePath":"en_US/developer/agent-development.md","lastUpdated":1792850916000}'),n={name:"en_US/developer/agent-development.md"};function o(r,e,l,d,c,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="agent-development" tabindex="-1">Agent development <a class="header-anchor" href="#agent-development" aria-label="Permalink to &quot;Agent development&quot;">​</a></h1><p>Agent is an independent Go program for collection, probes, and authorized operations. UI-only changes rarely require Agent changes; new collected fields or remote capabilities require coordination along the data path.</p><h2 id="build-and-isolate-a-test-instance" tabindex="-1">Build and isolate a test instance <a class="header-anchor" href="#build-and-isolate-a-test-instance" aria-label="Permalink to &quot;Build and isolate a test instance&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/nezhahq/agent.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agent</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> download</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/nezha-agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./cmd/agent</span></span></code></pre></div><p>Use the toolchain from <code>go.mod</code>. Release platform matrices and linker flags are in <code>.goreleaser.yml</code>. A default local build is not an official release; do not replace the installed system Agent for debugging.</p><p>Create separate <code>dev-config.yml</code> with a local test Dashboard and a test user&#39;s connection secret. Do not copy a production UUID. See <a href="/en_US/configuration/agent.html">Agent configuration</a> for addresses, TLS, and field formats. Run in the foreground:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/nezha-agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev-config.yml</span></span></code></pre></div><p>The default is <code>config.yml</code> beside the binary, not the shell working directory. Preserve the generated UUID; simultaneously running copies of one UUID confuses identity. Development normally needs no system-service installation: exit the foreground process to stop it.</p><h2 id="source-data-flow" tabindex="-1">Source data flow <a class="header-anchor" href="#source-data-flow" aria-label="Permalink to &quot;Source data flow&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Location</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>model/config.go</code></td><td>Fields, cloning, loading, validation, persistence</td></tr><tr><td><code>pkg/monitor</code></td><td>Host/state, interfaces, GPU, IP discovery</td></tr><tr><td><code>proto/nezha.proto</code></td><td>Dashboard gRPC message contract</td></tr><tr><td><code>cmd/agent</code></td><td>Connection, reporting, runtime snapshots, tasks, lifecycle</td></tr><tr><td>Capability packages such as <code>pkg/fm</code></td><td>File and transfer implementation</td></tr></tbody></table><p>For a new metric, follow collection through model/<code>PB()</code> conversion and protobuf, then Dashboard receiving, caching, HTTP/WS serialization, and theme rendering. An Agent field does not automatically create historical charts: explicitly integrate TSDB writes, query APIs, and frontend units too.</p><h2 id="runtime-configuration-changes" tabindex="-1">Runtime configuration changes <a class="header-anchor" href="#runtime-configuration-changes" aria-label="Permalink to &quot;Runtime configuration changes&quot;">​</a></h2><p>Multiple concurrent workers consume configuration. Follow the immutable runtime-snapshot design; do not mutate shared configuration or its maps/slices concurrently. For each new field, consider:</p><ol><li>YAML/JSON fields and default/range validation in <code>AgentConfig</code>.</li><li>Deep copies for new collections in <code>Clone()</code>.</li><li>Consumer-specific views that use one generation per operation.</li><li>Remote acceptance, deferred application, save-before-publish, recovery, and reconnects.</li><li>Startup-read versus reloadable behavior and matching documentation.</li></ol><p>Do not blindly execute <code>go generate ./...</code>: a directive does not prove its referenced generator exists in the current checkout. Follow actual tools and CI.</p><h2 id="task-development-beyond-the-happy-path" tabindex="-1">Task development beyond the happy path <a class="header-anchor" href="#task-development-beyond-the-happy-path" aria-label="Permalink to &quot;Task development beyond the happy path&quot;">​</a></h2><p>Commands, terminals, files, NAT, and probes have distinct disable gates. Reuse existing gates on new paths. Generic configuration pushes cannot rotate <code>client_secret</code>; server-transfer rotation uses a dedicated task and requires verified TLS on the next connection.</p><p>Propagate context, timeouts, and cancellation through slow operations. Reclaim goroutines, streams, files, and child processes when sessions end. Shell execution belongs only in explicit command functionality; never interpolate ordinary filenames into shell strings.</p><p>Cover disconnects, reconnects, cancellation, duplicated/out-of-order work, concurrent configuration changes, and resource-free shutdown. OS-sensitive tests should use temporary directories and isolated processes rather than modify real developer services.</p><h2 id="protobuf-and-cross-repository-compatibility" tabindex="-1">Protobuf and cross-repository compatibility <a class="header-anchor" href="#protobuf-and-cross-repository-compatibility" aria-label="Permalink to &quot;Protobuf and cross-repository compatibility&quot;">​</a></h2><p>Preserve existing field numbers and never reuse removed numbers. New fields must tolerate omission. Generated Go files are not hand-edited source. Regenerate matching Dashboard and Agent artifacts with compatible tools and record paired commits.</p><p>Dashboard <code>script/bootstrap.sh</code> also removes and copies the adjacent <code>../agent/proto</code>. It is not a side-effect-free Swagger command. For ordinary API docs, <a href="/en_US/developer/api.html">run swag alone</a>.</p><p>Basic local checks:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -mod=readonly</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -count=1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -mod=readonly</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -race</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -shuffle=on</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -count=1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./...</span></span></code></pre></div><p><code>-race</code> requires a supported platform/compiler. Cross-repository <code>agentcompat</code> workflows verify pinned Dashboard/Agent pairs. For protocol, connection, and task-lifecycle work, follow the current CI revisions and scenarios; ordinary unit tests are not equivalent. See <a href="/en_US/developer/testing.html">testing and contributions</a>.</p>`,25)])])}const u=t(n,[["render",o]]);export{g as __pageData,u as default};
